/**
 * Tiki-Data premium UI — isolated Cloudflare Pages preview gateway.
 * No API keys, provider requests, or D1 access. All APIs remain quality-gated.
 * Generated by premium/build.py: injects premium.css and premium-icons.js.
 */
const QA_ORIGIN='https://tiki-data-model-qa.pages.dev';
const PREMIUM_STYLE=/* inject_styles */ '';
const PREMIUM_ICONS=/* inject_icons */ '';
const HEADERS={'X-Robots-Tag':'noindex,nofollow','X-Content-Type-Options':'nosniff','Cache-Control':'no-store'};
export default{
  async fetch(request){
    try{
      if(request.method!=='GET'&&request.method!=='HEAD')return new Response('Method not allowed',{status:405,headers:HEADERS});
      const u=new URL(request.url);
      if(u.pathname==='/premium.css')return new Response(PREMIUM_STYLE,{headers:{...HEADERS,'Content-Type':'text/css; charset=utf-8'}});
      if(u.pathname==='/premium-icons.js')return new Response(PREMIUM_ICONS,{headers:{...HEADERS,'Content-Type':'application/javascript; charset=utf-8'}});
      const upstream=await fetch(new URL(u.pathname+u.search,QA_ORIGIN),{headers:{Accept:request.headers.get('Accept')||'*/*'},signal:AbortSignal.timeout(18000)});
      const headers=new Headers(upstream.headers);
      for(const [k,v]of Object.entries(HEADERS))headers.set(k,v);
      headers.delete('content-length');headers.delete('content-encoding');
      if((u.pathname==='/'||u.pathname==='/index.html')&&upstream.ok){
        const html=await upstream.text(); // HTML only; small QA page, never an arbitrary binary.
        const inject='<link rel="stylesheet" href="/premium.css"><script defer src="/premium-icons.js"></script>';
        return new Response(html.replace('</head>',inject+'</head>'),{status:upstream.status,headers:{...Object.fromEntries(headers),'Content-Type':'text/html; charset=utf-8'}});
      }
      return new Response(upstream.body,{status:upstream.status,headers});
    }catch(e){
      console.error(JSON.stringify({event:'premium_preview_gateway_error',type:String(e?.name||'error')}));
      return new Response(JSON.stringify({ok:false,error:'preview_temporarily_unavailable'}),{status:503,headers:{...HEADERS,'Content-Type':'application/json'}});
    }
  }
};